css:
/* ==== INTERFACE ====
   token  --bg #18191B        页面底色｜冷墨青灰整屏底子
   token  --surface #23262A   次级载体｜文本竹简对比区、引文槽底色
   token  --surface-raised #2E3339 悬浮卡片、交互激活背衬
   token  --text #EDEBE8      正文与主要提要文字｜高对比苍白
   token  --muted #9B9FA6     次级说明、文献出处、纯数字刻度
   token  --rule #3B4048      结构分割线、互见文本跨篇对照标尺
   token  --focus #4E7DA6     当前聚焦项、键盘焦点外圈
   token  --primary #4E7DA6   结构主色｜互见法篇目网络、结构主线、章节经纬（扛整套画面）
   token  --accent #E65A38    锐利强调｜太史公曰断语、冲突刺点、关键史料互勘微型标记（≤5%小面积）
   token  --fs-h1 34px        页标题
   token  --fs-h2 22px        区块标题、篇名并置栏头
   token  --fs-lead 19px      导语、篇章叙事假设
   token  --fs-body 18px      正文原典与叙事分析
   token  --fs-sec 16px       次级成句说明、人物对勘说明
   token  --fs-label 15px     互见连线标签、篇卷标识、控件标签
   token  --fs-tick 13px      时间轴刻度、篇章卷次序数
   token  --font-display "Noto Serif CJK SC", "AR PL SungtiL GB", serif
   token  --font-body "Noto Serif CJK SC", "AR PL SungtiL GB", serif
   token  --font-sans "Noto Sans CJK SC", "WenQuanYi Zen Hei", sans-serif
   token  --font-mono "Latin Modern Mono", "Noto Sans Mono", monospace
   版心   1488×844            #stage 已含 padding
   论点   《史记》的张力不在温情摹古，而在不同纪传彼此拼合、矛盾自现的冷峻手术刀感；深邃沉静的墨板底色托起经纬蓝主脉，唯一刺目的朱砂红只在太史公投掷个人断语或史实致命冲突处落下。
   材质   松烟墨与冷石刻碑：以不带暖粉的冷矿物墨色为底，文字如深刻于石壁的严密铭文，朱砂批注如刀锋点血。
   签名   跨篇目对勘时的垂直对照经纬网与「太史公曰」朱色针芒戳记。
   禁令   严禁采用任何暖黄或米色宣纸底；严禁将朱砂强调色铺满任何大面积色块或做渐变填充；严禁让篇章经纬蓝与朱砂红平分版面权重。
   修订   上一版因浅底被判定为奶油纸且强调色对比不足，改用冷墨石刻暗底，确立 4E7DA6 为唯一主色扛起互见网络，E65A38 为单点极锐利强调（明度与色相极差拉开到 30pp 以上）。
   ==== /INTERFACE ==== */

:root {
  --pad-x: 56px;
  --pad-y: 28px;

  --bg: #18191B;
  --surface: #23262A;
  --surface-raised: #2E3339;
  --text: #EDEBE8;
  --muted: #9B9FA6;
  --rule: #3B4048;

  --primary: #4E7DA6;
  --focus: #4E7DA6;
  --accent: #E65A38;

  --fs-h1: 34px;
  --fs-h2: 22px;
  --fs-lead: 19px;
  --fs-body: 18px;
  --fs-sec: 16px;
  --fs-label: 15px;
  --fs-tick: 13px;

  --lh-tight: 1.25;
  --lh-snug: 1.35;
  --lh-body: 1.6;
  --lh-loose: 1.75;

  --font-display: "Noto Serif CJK SC", "AR PL SungtiL GB", "AR PL UMing CN", serif;
  --font-body: "Noto Serif CJK SC", "AR PL SungtiL GB", "AR PL UMing CN", serif;
  --font-sans: "Noto Sans CJK SC", "WenQuanYi Zen Hei", sans-serif;
  --font-mono: "Latin Modern Mono", "Noto Sans Mono", monospace;

  --ease-standard: cubic-bezier(0.2, 0.0, 0.0, 1.0);
  --dur-instant: 100ms;
  --dur-short: 200ms;
  --dur-medium: 350ms;
}

@media (prefers-reduced-motion: reduce) {
  :root {
    --dur-instant: 0ms;
    --dur-short: 0ms;
    --dur-medium: 0ms;
  }
}
